 "matiere": { "key": "sante", "fr": "Santé", "nl": "Gezondheid", "en": "Health" },
 "titre": {
  "fr": "Kingston : le dernier site de consommation supervisée financé par l'Ontario devient un centre d'abstinence, budget doublé",
  "nl": "Kingston: de laatste door Ontario gefinancierde gebruiksruimte wordt een abstinentiecentrum, budget verdubbeld",
  "en": "Kingston: Ontario's last provincially funded consumption site becomes an abstinence hub, budget doubled"
 },
